// Generates CREDITS.md from the provenance tags in js/data.js, so the credits cannot drift from the data.
import { writeFileSync } from 'node:fs';
import * as D from '../js/data.js';

const out = ['# Credits and sources', '',
  'Generated by `node scripts/build-credits.mjs` from `js/data.js`. Do not edit by hand.', '',
  'Every value in the game is tagged as a published source, an exact defined constant, or a game assumption. `node scripts/check-sources.mjs` fails if any value is untagged.', '',
  '## Sources', '', '| Source | Publisher | Used for |', '|---|---|---|'];
for (const s of Object.values(D.SOURCES)) out.push(`| [${s.title}](${s.url}) | ${s.publisher} | ${s.usedFor} |`);

out.push('', '## Constants and allowances', '', '| Name | Value | Provenance |', '|---|---|---|');
for (const [k, v] of Object.entries(D.CONST)) {
  const prov = v.src ? `Source: [${D.SOURCES[v.src].title}](${D.SOURCES[v.src].url})${v.note ? '. ' + v.note : ''}` : v.defined ? `Defined: ${v.defined}` : `Assumption: ${v.assumption}`;
  out.push(`| \`${k}\` | ${v.value} ${v.unit || ''} | ${prov} |`);
}

out.push('', '## Catalogue entries', '', 'Launchers, instruments, radios, ground stations, teams, costs and budgets are generic game values unless a source is shown.', '', '| Group | Entry | Provenance |', '|---|---|---|');
const groups = { CLASSES: D.CLASSES, OBJECTIVES: D.OBJECTIVES, LAUNCHERS: D.LAUNCHERS, PROPULSION: D.PROPULSION, INSTRUMENTS: D.INSTRUMENTS, ANTENNAS: D.ANTENNAS, TRANSMITTERS: D.TRANSMITTERS,
  SHIELDING: D.SHIELDING, REDUNDANCY: D.REDUNDANCY, GROUND: D.GROUND, TRACKING: D.TRACKING, TEAMS: D.TEAMS, PIPELINES: D.PIPELINES, POLICIES: D.POLICIES, ...Object.fromEntries(Object.entries(D.ORBITS).map(([k, v]) => ['ORBITS.' + k, v])) };
for (const [g, list] of Object.entries(groups)) for (const e of list) {
  const prov = e.src ? `Source: [${D.SOURCES[e.src].title}](${D.SOURCES[e.src].url}). ${e.note || ''}` : `Assumption: ${e.assumption}`;
  out.push(`| ${g} | ${e.name} | ${prov.trim()} |`);
}

out.push('', '## Real missions shown in the debrief', '');
for (const m of Object.values(D.REAL_MISSIONS)) out.push(`- [${m.name}](${D.SOURCES[m.src].url}): ${m.fact}`);
out.push('', '## Assets', '', 'All graphics are drawn in code (SVG and CSS). All sound is synthesized in the browser with the Web Audio API. No third-party images, audio, fonts or libraries are used.', '',
  '## AI assistance', '', "This project was built with AI assistance (Anthropic's Claude) for code, data assembly and text.", '');
writeFileSync(new URL('../CREDITS.md', import.meta.url), out.join('\n'));
console.log(`CREDITS.md written: ${Object.keys(D.SOURCES).length} sources.`);
